css:
@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
  font-style: normal;
  font-weight: 400;
}

@page {
  size: 210mm 297mm;
  margin: 0;
}

html,
body {
  margin: 0 !important;
  padding: 0 !important;
}

.print-format {
  width: 210mm !important;
  min-height: 297mm !important;
  margin: 0 !important;
  padding: 0 !important;
  background: #fff !important;
}

.cdq,
.cdq * {
  box-sizing: border-box;
}

.cdq {
  --cd-document-ink: #202020;
  --cd-document-border: #202020;
  --cd-document-surface: #f1f1f1;
  --cd-document-accent: #e2a2f5;

  position: relative;

  width: 210mm;
  height: 297mm;

  margin: 0;

  overflow: hidden;

  color: var(--cd-document-ink);
  background: #fff;

  font-family:
    "TH Sarabun Document",
    "Noto Sans Thai",
    "TH Sarabun New",
    "TH SarabunPSK",
    sans-serif;

  font-size: 4.22mm;
  font-weight: 400;
  line-height: 1;

  page-break-after: always;

  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.cdq.last-page {
  page-break-after: auto;
}

.cdq p,
.cdq dl,
.cdq dt,
.cdq dd,
.cdq table {
  margin: 0;
  padding: 0;
}

.cdq strong,
.cdq b {
  font-weight: 700;
}


/* =========================================================
   HEADER
   Same corporate geometry as Purchase Order.
   ========================================================= */

.cdq .document-header {
  position: absolute;

  left: 0;
  top: 0;

  width: 210mm;
  height: 52.30mm;
}

.cdq .company-logo {
  position: absolute;

  left: 12.70mm;
  top: 18.56mm;

  width: 18.99mm;
  height: 7.25mm;

  object-fit: contain;
}

.cdq .company-name {
  position: absolute;

  left: 34.28mm;
  top: 13.62mm;

  width: 95mm;

  overflow: hidden;

  font-size: 6.20mm;
  font-weight: 700;
  line-height: 6.8mm;

  white-space: nowrap;
}

.cdq .company-address {
  position: absolute;

  left: 34.28mm;
  top: 22.82mm;

  width: 156mm;

  overflow: hidden;

  font-size: 4.22mm;
  line-height: 4.9mm;

  white-space: nowrap;
}

.cdq .company-contact {
  position: absolute;

  left: 34.28mm;
  top: 29.02mm;

  font-size: 4.22mm;
  line-height: 4.9mm;

  white-space: nowrap;
}

.cdq .company-tax-label,
.cdq .company-tax-value,
.cdq .company-branch {
  position: absolute;

  top: 35.63mm;

  font-size: 4.15mm;
  line-height: 5mm;

  white-space: nowrap;
}

.cdq .company-tax-label {
  left: 34.28mm;
}

.cdq .company-tax-value {
  left: 73.27mm;
}

.cdq .company-branch {
  left: 100.08mm;
}

.cdq .document-title,
.cdq .copy-title {
  position: absolute;

  left: 131.48mm;
  width: 59mm;

  display: -webkit-flex;
  display: flex;

  -webkit-align-items: center;
  align-items: center;

  -webkit-justify-content: center;
  justify-content: center;

  text-align: center;
  white-space: nowrap;
}

.cdq .document-title {
  top: 37.84mm;

  height: 8.20mm;

  padding: 0 2.5mm;

  border-radius: 6mm;

  background: var(--cd-document-accent);

  font-size: 6.25mm;
  font-weight: 700;
  line-height: 1;
}

.cdq .copy-title {
  top: 47.05mm;

  height: 5.50mm;

  font-size: 4.60mm;
  font-weight: 700;
  line-height: 1;
}


/* =========================================================
   BILINGUAL COMPACTION
   ========================================================= */

.cdq-bilingual .company-name {
  font-size: 5.25mm;
}

.cdq-bilingual .company-address,
.cdq-bilingual .company-contact,
.cdq-bilingual .company-tax-label,
.cdq-bilingual .company-tax-value,
.cdq-bilingual .company-branch {
  font-size: 3.70mm;
}

.cdq-bilingual .document-title {
  font-size: 5.50mm;
}

.cdq-bilingual .copy-title {
  font-size: 4.10mm;
}


/* =========================================================
   MAIN PAGE FLOW
   ========================================================= */

.cdq .document-main {
  position: absolute;

  left: 13.81mm;
  top: 52.30mm;

  width: 189.90mm;
  height: 236.85mm;

  display: -webkit-flex;
  display: flex;

  -webkit-flex-direction: column;
  flex-direction: column;

  -webkit-align-items: stretch;
  align-items: stretch;

  overflow: visible;
}

.cdq .info-box {
  -webkit-flex: 0 0 auto;
  flex: 0 0 auto;

  width: 100%;

  border: 0.24mm solid var(--cd-document-border);
  border-radius: 2.18mm;

  background: #fff;
}


/* =========================================================
   DOCUMENT META

   Row 1: Quotation No. / Date / Page
   Rows 2-4: Validity / Delivery Terms / Payment Terms

   All term labels have exactly the same width, so their
   label/value baselines line up consistently.
   ========================================================= */

.cdq .document-meta-box {
  padding: 2.75mm 3.60mm 2.70mm;
}

.cdq .meta-layout {
  width: 100%;
}


/* -------------------------
   Top row
   ------------------------- */

.cdq .meta-top-row {
  width: 100%;

  display: -webkit-flex;
  display: flex;

  -webkit-align-items: flex-start;
  align-items: flex-start;

  margin-bottom: 1.60mm;
}

.cdq .meta-top-item {
  min-width: 0;

  display: -webkit-flex;
  display: flex;

  -webkit-align-items: center;
  align-items: center;
}

.cdq .meta-quotation-no {
  -webkit-flex: 0 0 45%;
  flex: 0 0 45%;
}

.cdq .meta-date {
  -webkit-flex: 0 0 35%;
  flex: 0 0 35%;
}

.cdq .meta-page {
  -webkit-flex: 0 0 20%;
  flex: 0 0 20%;

  -webkit-justify-content: flex-end;
  justify-content: flex-end;
}

.cdq .meta-label {
  -webkit-flex: 0 0 auto;
  flex: 0 0 auto;

  margin-right: 1.80mm;

  font-size: 4.10mm;
  font-weight: 700;
  line-height: 4.65mm;

  white-space: nowrap;
}

.cdq .meta-value {
  -webkit-flex: 1 1 auto;
  flex: 1 1 auto;

  min-width: 0;

  font-size: 4.10mm;
  font-weight: 400;
  line-height: 4.65mm;

  white-space: nowrap;
  overflow: hidden;
  text-overflow: clip;
}

.cdq .meta-value-strong {
  font-size: 4.45mm;
  font-weight: 700;
}

.cdq .meta-page .meta-label {
  margin-right: 1mm;
}

.cdq .meta-page .meta-value {
  -webkit-flex: 0 0 auto;
  flex: 0 0 auto;

  overflow: visible;

  text-align: right;
}


/* -------------------------
   Terms rows
   ------------------------- */

.cdq .meta-terms {
  width: 100%;
}

.cdq .meta-term-row {
  width: 100%;

  display: -webkit-flex;
  display: flex;

  -webkit-align-items: flex-start;
  align-items: flex-start;

  padding: 0.55mm 0;
}

.cdq .meta-term-label {
  /*
    Fixed width is intentional.
    Validity, Delivery Terms and Payment Terms therefore
    always begin at exactly the same X position.
  */
  -webkit-flex: 0 0 42mm;
  flex: 0 0 42mm;

  padding-right: 2.20mm;

  font-size: 4.10mm;
  font-weight: 700;
  line-height: 4.65mm;

  white-space: nowrap;
}

.cdq .meta-term-value {
  -webkit-flex: 1 1 auto;
  flex: 1 1 auto;

  min-width: 0;

  font-size: 4.10mm;
  font-weight: 400;
  line-height: 4.65mm;

  white-space: normal;
  overflow: visible;

  overflow-wrap: anywhere;
  word-break: break-word;
}

.cdq .meta-highlight {
  display: inline;

  padding: 0.15mm 0.70mm 0.30mm;

  border-radius: 1mm;

  background: var(--cd-document-accent);

  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}


/* -------------------------
   Bilingual compaction
   ------------------------- */

.cdq-bilingual .meta-label,
.cdq-bilingual .meta-term-label {
  font-size: 3.35mm;
}

.cdq-bilingual .meta-value,
.cdq-bilingual .meta-term-value {
  font-size: 3.65mm;
}

.cdq-bilingual .meta-term-label {
  -webkit-flex-basis: 48mm;
  flex-basis: 48mm;
}

/* =========================================================
   CUSTOMER / ATTENTION / SALES CONTACT
   Auto-height.
   ========================================================= */

.cdq .party-contact-box {
  margin-top: 2.40mm;
  padding: 3mm 3.60mm 3.20mm;
}

.cdq .party-grid {
  width: 100%;

  display: -webkit-flex;
  display: flex;

  -webkit-align-items: stretch;
  align-items: stretch;
}

.cdq .customer-attention-section {
  -webkit-flex: 1.90 1 0;
  flex: 1.90 1 0;
}

.cdq .sales-section {
  -webkit-flex: 0.75 1 0;
  flex: 0.75 1 0;
}

.cdq .party-section {
  min-width: 0;

  height: auto;

  padding: 0 3.60mm;

  overflow: visible;
}

.cdq .party-section:first-child {
  padding-left: 0;
}

.cdq .party-section:last-child {
  padding-right: 0;
}

.cdq .party-section + .party-section {
  border-left: 0.24mm solid var(--cd-document-border);
}

.cdq .section-heading {
  display: -webkit-flex;
  display: flex;

  -webkit-flex-wrap: wrap;
  flex-wrap: wrap;

  -webkit-align-items: baseline;
  align-items: baseline;

  gap: 1.80mm;

  margin: 0 0 1.20mm;
}

.cdq .section-title {
  font-size: 4.22mm;
  font-weight: 700;
  line-height: 4.80mm;

  white-space: nowrap;
}

.cdq .party-code {
  font-size: 4.10mm;
  line-height: 4.80mm;

  white-space: nowrap;
}

.cdq .section-primary {
  margin: 0 0 0.80mm;

  font-size: 4.22mm;
  line-height: 4.45mm;

  white-space: normal;

  overflow-wrap: anywhere;
  word-break: break-word;
}

.cdq .section-content {
  min-width: 0;

  height: auto;
  min-height: 0;

  margin: 0;
  padding: 0;

  overflow: visible;

  font-size: 4.10mm;
  line-height: 4.20mm;

  white-space: normal;

  overflow-wrap: anywhere;
  word-break: break-word;
}

/* Customer and Attention are inside the same physical section. */
.cdq .attention-row {
  width: 100%;

  display: -webkit-flex;
  display: flex;

  -webkit-align-items: flex-start;
  align-items: flex-start;

  margin: 0 0 1.70mm;
}

.cdq .attention-label {
  -webkit-flex: 0 0 18mm;
  flex: 0 0 18mm;

  padding-right: 2mm;

  font-size: 4.22mm;
  font-weight: 700;
  line-height: 4.50mm;

  white-space: nowrap;
}

.cdq .attention-value {
  -webkit-flex: 1 1 auto;
  flex: 1 1 auto;

  min-width: 0;

  font-size: 4.10mm;
  line-height: 4.20mm;

  white-space: normal;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.cdq .customer-code-plain {
  -webkit-flex: 0 0 auto;
  flex: 0 0 auto;

  margin-left: 3mm;

  font-size: 3.90mm;
  line-height: 4.20mm;

  text-align: right;
  white-space: nowrap;
}

.cdq .attention-value p {
  margin: 0 !important;
  padding: 0 !important;

  font: inherit !important;
  line-height: inherit !important;
}

.cdq .customer-row {
  width: 100%;

  padding-top: 0.80mm;
}

.cdq .customer-name-plain {
  margin: 0 0 1.00mm;

  font-size: 4.22mm;
  line-height: 4.45mm;

  white-space: normal;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.cdq-bilingual .customer-name-plain {
  font-size: 3.75mm;
}

.cdq-bilingual .attention-label {
  font-size: 3.70mm;
}

.cdq-bilingual .attention-value {
  font-size: 3.75mm;
}

.cdq-bilingual .customer-code-plain {
  font-size: 3.55mm;
}

.cdq .address-display p,
.cdq .sales-contact-display p {
  margin: 0 !important;
  padding: 0 !important;

  font: inherit !important;
  line-height: inherit !important;
}

.cdq .address-display br,
.cdq .sales-contact-display br {
  display: block !important;
}

.cdq-bilingual .section-title {
  font-size: 3.70mm;
}

.cdq-bilingual .section-primary,
.cdq-bilingual .section-content,
.cdq-bilingual .party-code {
  font-size: 3.75mm;
}


/* =========================================================
   INTRO
   ========================================================= */

.cdq .quotation-intro {
  -webkit-flex: 0 0 auto;
  flex: 0 0 auto;

  margin: 2.60mm 0 2mm;

  padding-left: 1.20mm;

  font-size: 4.10mm;
  font-weight: 700;
  line-height: 5mm;
}

.cdq-bilingual .quotation-intro {
  font-size: 3.50mm;
}


/* =========================================================
   QUOTATION GRID
   ========================================================= */

.cdq .quotation-grid {
  position: relative;

  -webkit-flex: 1 1 auto;
  flex: 1 1 auto;

  width: 100%;
  min-height: 105mm;

  display: -webkit-flex;
  display: flex;

  -webkit-flex-direction: column;
  flex-direction: column;

  overflow: hidden;

  border: 0.24mm solid var(--cd-document-border);
  border-radius: 2.18mm 2.18mm 0 0;
}


/* Product header */

.cdq .product-head {
  position: static;

  -webkit-flex: 0 0 8.64mm;
  flex: 0 0 8.64mm;

  width: 100%;
  height: 8.64mm;

  display: -webkit-flex;
  display: flex;

  border-bottom: 0.24mm solid var(--cd-document-border);

  background: var(--cd-document-surface);

  font-weight: 700;
}

.cdq .head-cell {
  min-width: 0;
  height: 8.64mm;

  display: -webkit-flex;
  display: flex;

  -webkit-align-items: center;
  align-items: center;

  -webkit-justify-content: center;
  justify-content: center;

  padding: 0.35mm 0.55mm;

  border-right: 0.24mm solid var(--cd-document-border);

  font-size: 4.05mm;
  line-height: 4mm;

  text-align: center;

  overflow: hidden;
}

.cdq .product-head .col-no {
  -webkit-flex: 0 0 11mm;
  flex: 0 0 11mm;
}

.cdq .product-head .col-description {
  -webkit-flex: 0 0 89.90mm;
  flex: 0 0 89.90mm;
}

.cdq .product-head .col-quantity {
  -webkit-flex: 0 0 30mm;
  flex: 0 0 30mm;
}

.cdq .product-head .col-rate {
  -webkit-flex: 0 0 29.50mm;
  flex: 0 0 29.50mm;
}

.cdq .product-head .col-amount {
  -webkit-flex: 0 0 29.50mm;
  flex: 0 0 29.50mm;

  border-right: 0;
}

.cdq-bilingual .head-cell {
  font-size: 3.35mm;
}


/* Product body */

.cdq .product-body {
  position: relative;

  -webkit-flex: 1 1 auto;
  flex: 1 1 auto;

  min-height: 55mm;

  overflow: hidden;

  border-bottom: 0.24mm solid var(--cd-document-border);
}

.cdq .item-lines {
  width: 100%;
  height: 100%;

  margin: 0;
  border: 0;

  border-collapse: separate;
  border-spacing: 0;

  table-layout: fixed;

  background: transparent;
}

.cdq .item-lines col.col-no {
  width: 11mm;
}

.cdq .item-lines col.col-description {
  width: 89.90mm;
}

.cdq .item-lines col.col-quantity {
  width: 30mm;
}

.cdq .item-lines col.col-rate {
  width: 29.50mm;
}

.cdq .item-lines col.col-amount {
  width: 29.50mm;
}

.cdq .item-lines td {
  margin: 0;

  border: 0 !important;
  border-right: 0.24mm solid var(--cd-document-border) !important;

  overflow: hidden;

  font-size: 4.10mm;
  line-height: 4.25mm;

  vertical-align: top !important;
}

.cdq .item-lines td:last-child {
  border-right: 0 !important;
}

.cdq .item-lines .item-row td {
  height: 8.50mm;

  padding: 2mm 1.15mm 0.65mm;
}

.cdq .item-lines .cell-no {
  text-align: center;
}

.cdq .item-lines .cell-description {
  padding-left: 1.35mm;
  padding-right: 1mm;
}

.cdq .item-lines .cell-quantity {
  text-align: center;
  white-space: nowrap;
}

.cdq .item-lines .cell-money {
  padding-right: 1.25mm;

  text-align: right;
  white-space: nowrap;
}

.cdq .item-lines .fill-row {
  height: 100%;
}

.cdq .item-lines .fill-row td {
  height: 100%;
  padding: 0 !important;
}

.cdq-bilingual .item-lines td {
  font-size: 3.65mm;
}


/* =========================================================
   SUMMARY
   ========================================================= */

.cdq .summary-area {
  position: relative;

  -webkit-flex: 0 0 27mm;
  flex: 0 0 27mm;

  width: 100%;
  height: 27mm;

  display: -webkit-flex;
  display: flex;

  border-bottom: 0.24mm solid var(--cd-document-border);
}

.cdq .remarks-panel {
  position: relative;

  -webkit-flex: 0 0 100.90mm;
  flex: 0 0 100.90mm;

  height: 100%;

  padding: 3mm 4.75mm 2.50mm;

  border-right: 0.24mm solid var(--cd-document-border);

  overflow: hidden;
}

.cdq .remarks-title {
  font-size: 4.22mm;
  font-weight: 700;
  line-height: 5mm;
}

.cdq .remarks-body {
  margin-top: 1.10mm;

  max-height: 10mm;

  overflow: hidden;

  font-size: 4.05mm;
  line-height: 4.25mm;
}

.cdq .remarks-sales-contact {
  margin-top: 1mm;

  font-size: 3.85mm;
  line-height: 4.10mm;
}

.cdq .totals-panel {
  -webkit-flex: 1 1 auto;
  flex: 1 1 auto;

  height: 100%;

  padding: 2.20mm 1.55mm 1.50mm 4mm;
}

.cdq .total-line {
  height: 7mm;

  display: -webkit-flex;
  display: flex;

  -webkit-align-items: center;
  align-items: center;
}

.cdq .total-line-label {
  -webkit-flex: 1 1 auto;
  flex: 1 1 auto;

  min-width: 0;

  padding-right: 2mm;

  font-size: 4.05mm;
  font-weight: 700;
  line-height: 4.50mm;
}

.cdq .total-line-value {
  -webkit-flex: 0 0 27mm;
  flex: 0 0 27mm;

  font-size: 4.10mm;
  line-height: 4.50mm;

  text-align: right;
}

.cdq .total-line-grand .total-line-label,
.cdq .total-line-grand .total-line-value {
  font-weight: 700;
}

.cdq-bilingual .total-line-label {
  font-size: 3.45mm;
}


/* Amount in words */

.cdq .words-row {
  -webkit-flex: 0 0 9.59mm;
  flex: 0 0 9.59mm;

  width: 100%;
  height: 9.59mm;

  padding: 2.30mm 2mm 0;

  background: var(--cd-document-surface);

  font-size: 4.05mm;
  font-weight: 700;
  line-height: 5mm;

  text-align: right;

  overflow: hidden;

  white-space: nowrap;
}

.cdq-bilingual .words-row {
  font-size: 3.45mm;
}


/* =========================================================
   FOOTER: BANK / SIGNATURE
   Same framed treatment as PO approval box.
   ========================================================= */

.cdq .quotation-footer {
  -webkit-flex: 0 0 29.20mm;
  flex: 0 0 29.20mm;

  width: 100%;
  height: 29.20mm;

  display: -webkit-flex;
  display: flex;

  overflow: hidden;

  border: 0.24mm solid var(--cd-document-border);
  border-top: 0;
  border-radius: 0 0 2.18mm 2.18mm;
}

.cdq .bank-panel {
  -webkit-flex: 0 0 100.90mm;
  flex: 0 0 100.90mm;

  height: 100%;

  padding: 2.20mm 4mm 1.50mm;

  border-right: 0.24mm solid var(--cd-document-border);
}

.cdq .footer-title {
  margin-bottom: 1.20mm;

  font-size: 4.10mm;
  font-weight: 700;
  line-height: 4.60mm;
}

.cdq .bank-grid {
  width: 100%;

  display: -webkit-flex;
  display: flex;

  -webkit-flex-wrap: wrap;
  flex-wrap: wrap;
}

.cdq .bank-label {
  width: 24mm;

  font-size: 3.95mm;
  font-weight: 700;
  line-height: 4.35mm;
}

.cdq .bank-value {
  width: calc(50% - 24mm);

  font-size: 3.95mm;
  line-height: 4.35mm;
}

.cdq .signature-panel {
  position: relative;

  -webkit-flex: 1 1 auto;
  flex: 1 1 auto;

  height: 100%;

  text-align: center;
}

.cdq .respect-text {
  position: absolute;

  left: 0;
  top: 2.50mm;

  width: 100%;

  font-size: 4.05mm;
  line-height: 4.50mm;
}

.cdq .signature-line {
  position: absolute;

  left: 18mm;
  right: 18mm;
  top: 17.80mm;

  border-top: 0.24mm solid var(--cd-document-border);
}

.cdq .signature-name {
  position: absolute;

  left: 3mm;
  right: 3mm;
  top: 19.20mm;

  overflow: hidden;

  font-size: 4.05mm;
  line-height: 4.50mm;

  white-space: nowrap;
}

.cdq .signature-role {
  position: absolute;

  left: 3mm;
  right: 3mm;
  top: 23.40mm;

  overflow: hidden;

  font-size: 3.90mm;
  line-height: 4.30mm;

  white-space: nowrap;
}

.cdq-bilingual .footer-title,
.cdq-bilingual .bank-label,
.cdq-bilingual .bank-value,
.cdq-bilingual .respect-text,
.cdq-bilingual .signature-name,
.cdq-bilingual .signature-role {
  font-size: 3.45mm;
}


/* =========================================================
   PRINT SAFETY
   ========================================================= */

@media print {

  .cdq .document-meta-box,
  .cdq .party-contact-box,
  .cdq .quotation-grid,
